/**
 * The Celestara mark: a serif "C" that is an elliptical ring - thick on the
 * left, hairline along the top and bottom, ending in a point at the bottom -
 * running over the top into a slim four-point star, with a thin orbit that
 * passes in front of the C at the bottom and tucks behind it and the star.
 *
 * One colour: it takes the surrounding text colour, so the C and the star read
 * as a single joined shape. Decorative - the wordmark beside it carries the
 * name. `simple` drops the orbit, which would blur to nothing at favicon size.
 *
 * The path data is generated by design/make_logo.py (from measurements of the
 * reference drawing); run it again rather than editing the numbers by hand.
 */

const C_PATH = "M49.1 22.47A19.48 22.09 0 1 0 43.21 51.77C42.96 51.92 42.22 52.43 41.68 52.7C41.14 52.96 40.54 53.18 39.96 53.37C39.38 53.56 38.77 53.7 38.2 53.82C37.63 53.93 37.05 54.01 36.51 54.08C35.97 54.14 35.45 54.17 34.96 54.19C34.47 54.22 34 54.22 33.55 54.23C33.09 54.23 32.45 54.23 32.23 54.23A15.19 20.71 0 1 1 45.38 23.16Z";
const STAR_PATH = "M43.2 8.12C46.02 20.4 44.5 18.88 56.78 21.7C44.5 24.53 46.02 23 43.2 35.28C40.38 23 41.9 24.53 29.62 21.7C41.9 18.88 40.38 20.4 43.2 8.12Z";
const ORBIT_PATH = "M13.51 32.38A28.77 12.33 -16.53 1 0 51.45 23.76";

export function LogoMark({
  size = 28,
  simple = false,
  className,
}: {
  size?: number;
  simple?: boolean;
  className?: string;
}) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 64 64"
      aria-hidden="true"
      focusable="false"
      className={className}
    >
      <path d={C_PATH} fill="currentColor" />
      {!simple && (
        <path
          d={ORBIT_PATH}
          fill="none"
          stroke="currentColor"
          strokeWidth="0.75"
          strokeLinecap="round"
        />
      )}
      <path d={STAR_PATH} fill="currentColor" />
    </svg>
  );
}
